import Foundation
import SwiftData

@Observable
final class PatientListViewModel {
    var searchQuery: String = ""
    var patients: [Patient] = []
    var hasMore: Bool = true

    private let patientRepo: PatientRepository = PatientRepositoryImpl()
    private let pageSize = 20
    private var currentPage = 0

    func loadPatients(context: ModelContext) {
        let trimmedQuery = searchQuery.trimmingCharacters(in: .whitespacesAndNewlines)

        if trimmedQuery.isEmpty {
            // Paginated load — reset to first page
            currentPage = 0
            let results = patientRepo.getPaginated(limit: pageSize, offset: 0, context: context)
            patients = results
            hasMore = results.count == pageSize
        } else {
            // Search loads all matching (no pagination)
            patients = patientRepo.search(query: trimmedQuery, context: context)
            hasMore = false
        }
    }

    func loadMore(context: ModelContext) {
        let trimmedQuery = searchQuery.trimmingCharacters(in: .whitespacesAndNewlines)
        guard trimmedQuery.isEmpty, hasMore else { return }

        currentPage += 1
        let results = patientRepo.getPaginated(limit: pageSize, offset: currentPage * pageSize, context: context)
        patients.append(contentsOf: results)
        hasMore = results.count == pageSize
    }
}

